document.addEventListener('DOMContentLoaded', () => {
    const form = document.getElementById('contact-form');
    const status = document.getElementById('form-status');

    form.addEventListener('submit', (e) => {
        e.preventDefault();

        // Basic validation check (even if we don't show inline errors initially)
        if (!form.checkValidity()) {
            status.textContent = 'Please fill out all required fields correctly.';
            status.className = '';
            status.style.color = 'var(--error-color)';
            return;
        }

        // Simulate form submission
        const submitButton = form.querySelector('button');
        const originalText = submitButton.textContent;

        submitButton.disabled = true;
        submitButton.textContent = 'Sending...';

        setTimeout(() => {
            status.textContent = 'Thank you! Your request has been sent.';
            status.className = 'success';
            status.style.color = ''; // Reset to CSS class color
            form.reset();
            submitButton.disabled = false;
            submitButton.textContent = originalText;
        }, 1500);
    });
});

