            <div class="form-field">
                <label for="full-name">Full Name <span aria-hidden="true">*</span></label>
                <input type="text" id="full-name" name="full-name" required aria-required="true" autocomplete="name">
                <span id="name-error" class="error-message">Error: Please enter your full name.</span>
            </div>

            <div class="form-field">
                <label for="email">Email Address <span aria-hidden="true">*</span></label>
                <input type="email" id="email" name="email" required aria-required="true" autocomplete="email">
                <span id="email-error" class="error-message">Error: Please enter a valid email address.</span>
            </div>

            <div class="form-field">
                <label for="phone">Phone Number (Optional)</label>
                <input type="tel" id="phone" name="phone" aria-describedby="phone-helper" autocomplete="tel">
                <span id="phone-helper" class="helper-text">Format: +1 (555) 000-0000</span>
