        document.addEventListener('DOMContentLoaded', () => {
            const form = document.getElementById('contact-form');
            const status = document.getElementById('form-status');

            form.addEventListener('submit', (e) => {
                e.preventDefault();

                // Reset errors
                const inputs = form.querySelectorAll('input');
                const errorMessages = form.querySelectorAll('.error-message');
                let firstInvalid = null;

                inputs.forEach(input => {
                    input.setAttribute('aria-invalid', 'false');
                    input.removeAttribute('aria-describedby');
                    // Re-add phone helper if it's the phone input
                    if (input.id === 'phone') {
                        input.setAttribute('aria-describedby', 'phone-helper');
                    }
                });

                errorMessages.forEach(msg => msg.style.display = 'none');

                // Validation logic
                let isValid = true;

                inputs.forEach(input => {
                    if (!input.checkValidity()) {
                        isValid = false;
                        input.setAttribute('aria-invalid', 'true');

                        const errorId = `${input.id}-error`;
                        const errorMsg = document.getElementById(errorId);
                        if (errorMsg) {
                            errorMsg.style.display = 'block';
                            const currentDescribedBy = input.getAttribute('aria-describedby') || '';
                            input.setAttribute('aria-describedby', `${currentDescribedBy} ${errorId}`.trim());
                        }

                        if (!firstInvalid) firstInvalid = input;
                    }
                });

                if (!isValid) {
                    status.textContent = 'Please correct the errors in the form.';
                    status.style.color = 'var(--error-color)';
                    if (firstInvalid) firstInvalid.focus();
                    return;
                }

                // Simulate form submission
                const submitButton = form.querySelector('button');
                const originalText = submitButton.textContent;

                submitButton.disabled = true;
                submitButton.textContent = 'Sending...';
                status.textContent = 'Submitting your request...';
                status.style.color = 'var(--text-color)';

                setTimeout(() => {
                    status.textContent = 'Thank you! Your request has been sent successfully.';
                    status.style.color = '#059669'; // Success green
                    form.reset();
                    submitButton.disabled = false;
                    submitButton.textContent = originalText;
                }, 1500);
            });
        });
    </script>
</body>
</html>
