<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Support - Contact Us</title>
    <style>
        :root {
            --primary-color: #0066ff;
            --primary-hover: #0052cc;
            --bg-color: #f8fafc;
            --card-bg: #ffffff;
            --text-color: #1e293b;
            --text-muted: #475569;
            --border-color: #cbd5e1;
            --input-focus: #0066ff;
            --error-color: #b91c1c;
            --radius: 8px;
            --shadow: 0 4px 6px -1px rgb(0 0 0 / 0.1), 0 2px 4px -2px rgb(0 0 0 / 0.1);
        }

        * {
            box-sizing: border-box;
            margin: 0;
            padding: 0;
        }

        body {
            font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
            background-color: var(--bg-color);
            color: var(--text-color);
            line-height: 1.5;
            display: flex;
            justify-content: center;
            align-items: center;
            min-height: 100vh;
            padding: 20px;
        }

        .container {
            background: var(--card-bg);
            padding: 40px;
            border-radius: var(--radius);
            box-shadow: var(--shadow);
            max-width: 480px;
            width: 100%;
        }

        h1 {
            font-size: 24px;
            margin-bottom: 8px;
            font-weight: 700;
        }

        .description {
            color: var(--text-muted);
            margin-bottom: 32px;
        }

        .form-field {
            margin-bottom: 24px;
            display: flex;
            flex-direction: column;
        }

        label {
            font-size: 14px;
            font-weight: 600;
            margin-bottom: 8px;
        }

        input {
            padding: 12px 16px;
            border: 1px solid var(--border-color);
            border-radius: var(--radius);
            font-size: 16px;
            transition: border-color 0.2s, box-shadow 0.2s;
            outline: none;
        }

        input:focus {
            border-color: var(--input-focus);
            box-shadow: 0 0 0 3px rgba(0, 102, 255, 0.1);
        }

        .helper-text {
            font-size: 12px;
            color: var(--text-muted);
            margin-top: 4px;
        }

        button {
            background-color: var(--primary-color);
            color: white;
            border: none;
            padding: 14px;
            border-radius: var(--radius);
            font-size: 16px;
            font-weight: 600;
            cursor: pointer;
            transition: background-color 0.2s;
            width: 100%;
            margin-top: 8px;
        }

        button:hover {
            background-color: var(--primary-hover);
        }

        #form-status {
            margin-top: 24px;
            text-align: center;
            font-weight: 500;
        }

        .skip-link {
            position: absolute;
            top: -100px;
            left: 10px;
            background: var(--primary-color);
            color: white;
            padding: 10px 20px;
            z-index: 100;
            transition: top 0.2s;
            text-decoration: none;
            border-radius: var(--radius);
        }

        .skip-link:focus {
            top: 10px;
        }

        .required-notice {
            font-size: 14px;
            margin-bottom: 24px;
            color: var(--text-muted);
        }

        .error-message {
            display: none;
            color: var(--error-color);
            font-size: 14px;
            margin-top: 4px;
            font-weight: 500;
        }

        input[aria-invalid="true"] {
            border-color: var(--error-color);
        }

        input[aria-invalid="true"]:focus {
            box-shadow: 0 0 0 3px rgba(185, 28, 28, 0.1);
        }
    </style>
</head>
<body>
    <a href="#main-content" class="skip-link">Skip to main content</a>
    <main class="container" id="main-content">
        <h1>Contact Support</h1>
        <p class="description">Fill out the form below and we'll get back to you as soon as possible.</p>

        <p class="required-notice" aria-hidden="true">Fields marked with * are required.</p>

        <form id="contact-form" novalidate>
            <div class="form-field">
                <label for="full-name">Full Name <span aria-hidden="true">*</span></label>
                <input type="text" id="full-name" name="full-name" required aria-required="true" autocomplete="name">
                <span id="name-error" class="error-message">Error: Please enter your full name.</span>
            </div>

            <div class="form-field">
                <label for="email">Email Address <span aria-hidden="true">*</span></label>
                <input type="email" id="email" name="email" required aria-required="true" autocomplete="email">
                <span id="email-error" class="error-message">Error: Please enter a valid email address.</span>
            </div>

            <div class="form-field">
                <label for="phone">Phone Number (Optional)</label>
                <input type="tel" id="phone" name="phone" aria-describedby="phone-helper" autocomplete="tel">
                <span id="phone-helper" class="helper-text">Format: +1 (555) 000-0000</span>
                <span id="phone-error" class="error-message">Error: Please enter a valid phone number.</span>
            </div>

            <button type="submit">Submit Request</button>
        </form>
        <div id="form-status" aria-live="polite" role="status"></div>
    </main>

    <script>
        document.addEventListener('DOMContentLoaded', () => {
            const form = document.getElementById('contact-form');
            const status = document.getElementById('form-status');

            form.addEventListener('submit', (e) => {
                e.preventDefault();

                // Reset errors
                const inputs = form.querySelectorAll('input');
                const errorMessages = form.querySelectorAll('.error-message');
                let firstInvalid = null;

                inputs.forEach(input => {
                    input.setAttribute('aria-invalid', 'false');
                    input.removeAttribute('aria-describedby');
                    // Re-add phone helper if it's the phone input
                    if (input.id === 'phone') {
                        input.setAttribute('aria-describedby', 'phone-helper');
                    }
                });

                errorMessages.forEach(msg => msg.style.display = 'none');

                // Validation logic
                let isValid = true;

                inputs.forEach(input => {
                    if (!input.checkValidity()) {
                        isValid = false;
                        input.setAttribute('aria-invalid', 'true');

                        const errorId = `${input.id}-error`;
                        const errorMsg = document.getElementById(errorId);
                        if (errorMsg) {
                            errorMsg.style.display = 'block';
                            const currentDescribedBy = input.getAttribute('aria-describedby') || '';
                            input.setAttribute('aria-describedby', `${currentDescribedBy} ${errorId}`.trim());
                        }

                        if (!firstInvalid) firstInvalid = input;
                    }
                });

                if (!isValid) {
                    status.textContent = 'Please correct the errors in the form.';
                    status.style.color = 'var(--error-color)';
                    if (firstInvalid) firstInvalid.focus();
                    return;
                }

                // Simulate form submission
                const submitButton = form.querySelector('button');
                const originalText = submitButton.textContent;

                submitButton.disabled = true;
                submitButton.textContent = 'Sending...';
                status.textContent = 'Submitting your request...';
                status.style.color = 'var(--text-color)';

                setTimeout(() => {
                    status.textContent = 'Thank you! Your request has been sent successfully.';
                    status.style.color = '#059669'; // Success green
                    form.reset();
                    submitButton.disabled = false;
                    submitButton.textContent = originalText;
                }, 1500);
            });
        });
    </script>
</body>
</html>
